<?php require_once __DIR__."/../config/auth.php";require_login();$id=(int)$_GET["id"];$s=db()->prepare("SELECT i.*,u.name user_name FROM invoices i JOIN users u ON u.id=i.user_id WHERE i.id=?");$s->execute([$id]);$i=$s->fetch();$s=db()->prepare("SELECT * FROM invoice_items WHERE invoice_id=?");$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title><?=e($i["invoice_no"])?></title><style>body{width:76mm;max-width:76mm;margin:auto;font-family:Arial;font-size:12px}.c{text-align:center}.r{display:flex;justify-content:space-between;border-bottom:1px dashed #888;padding:4px 0}.big{font-size:18px;font-weight:bold}@media print{.np{display:none}}</style></head><body><div class="np c"><button onclick="print()">طباعة / Print</button></div><div class="c"><h2>RetailFlow</h2><div><?=e($i["invoice_no"])?></div><div><?=e($i["created_at"])?></div></div><hr><?php foreach($items as $x):?><div class="r"><span><?=e($x["product_name"])?><br>x <?=$x["qty"]?></span><b><?=number_format($x["line_total"],2)?></b></div><?php endforeach;?><div class="r"><span>Subtotal</span><b><?=number_format($i["subtotal"],2)?></b></div><div class="r"><span>Discount</span><b><?=number_format($i["discount"],2)?></b></div><div class="r big"><span>Total</span><b><?=number_format($i["total"],2)?></b></div><div class="r"><span>Paid</span><b><?=number_format($i["paid"],2)?></b></div><div class="r"><span>Change</span><b><?=number_format($i["change_amount"],2)?></b></div><p class="c">شكراً لزيارتكم<br>Thank you</p><script>onload=()=>setTimeout(()=>print(),250)</script></body></html>